import Foundationstruct User {    let uid: String    let name: String    let email: String    let phone: String    let userType: String   // example: "Donor" or "Receiver"        // Convert User object to Dictionary for Firebase    func toDictionary() -> [String: Any] {        return [            "uid": uid,            "name": name,            "email": email,            "phone": phone,            "userType": userType        ]    }}